// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const query = input.query || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation discord_user_id ---
const discordUserId = query.discord_user_id;

if (!discordUserId) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le parametre "discord_user_id" est requis'
  };
}

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    discord_user_id: discordUserId,
    project_id: projectId
  }
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const apiResponse = $input.first().json;
const validationData = $('Validate Input').first().json;

// --- Check API errors ---
if (apiResponse.error || apiResponse.success === false) {
  return {
    success: false,
    error: {
      code: apiResponse.error?.code || 'PROFILE_NOT_FOUND',
      message: apiResponse.error?.message || 'Profil non trouve',
      http_status: apiResponse.error?.http_status || 404
    }
  };
}

// --- Format profile ---
const profile = apiResponse.profile || apiResponse;

// --- Format addresses ---
const addresses = (profile.addresses || []).map(addr => ({
  id: addr.id,
  label: addr.label || null,
  full_name: addr.full_name,
  phone: addr.phone || null,
  line1: addr.line1,
  line2: addr.line2 || null,
  city: addr.city,
  postal_code: addr.postal_code,
  country_code: addr.country_code || 'FR',
  is_default: addr.is_default || false
}));

// --- Success response ---
return {
  success: true,
  profile: {
    discord_user_id: profile.discord_user_id || validationData.data.discord_user_id,
    email: profile.email || null,
    phone: profile.phone || null,
    addresses: addresses,
    default_address_id: profile.default_address_id || addresses.find(a => a.is_default)?.id || null,
    created_at: profile.created_at,
    updated_at: profile.updated_at
  }
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};

